def create_reference_foundation(apps, schema_editor):
    ReferenceDictionary = apps.get_model("reference_data", "ReferenceDictionary")
    DictionaryType = apps.get_model("reference_data", "DictionaryType")
    Country = apps.get_model("reference_data", "Country")
    SystemParameterDefinition = apps.get_model("reference_data", "SystemParameterDefinition")
    SystemParameterValue = apps.get_model("reference_data", "SystemParameterValue")
    ConfigRelease = apps.get_model("reference_data", "ConfigRelease")

    category_codes = list(
        ReferenceDictionary.objects.order_by("category_code")
        .values_list("category_code", flat=True)
        .distinct()
    )
    for code in category_codes:
        chinese_name, english_name, group_code, sort_order = TYPE_METADATA.get(
            code,
            (code, code.replace("_", " ").title(), "OTHER", 999),
        )
        dictionary_type = DictionaryType.objects.create(
            id=uuid.uuid5(TYPE_NAMESPACE, code),
            code=code,
            chinese_name=chinese_name,
            english_name=english_name,
            group_code=group_code,
            status="ACTIVE",
            sort_order=sort_order,
            description="由现有字典分类兼容迁移生成。",
        )
        ReferenceDictionary.objects.filter(category_code=code).update(dictionary_type_id=dictionary_type.id)

    country_items = ReferenceDictionary.objects.filter(category_code="COUNTRY_REGION")
    for item in country_items:
        country_data = COUNTRIES.get(item.item_code)
        if country_data is None:
            continue
        alpha3_code, numeric_code, chinese_name, english_name = country_data
        Country.objects.create(
            id=uuid.uuid5(MASTER_DATA_NAMESPACE, f"COUNTRY:{item.item_code}"),
            code=item.item_code,
            alpha3_code=alpha3_code,
            numeric_code=numeric_code,
            chinese_name=chinese_name,
            english_name=english_name,
            status=item.status,
            sort_order=item.sort_order,
            source_version="ISO 3166-1 snapshot 2026-08-26",
            description="由现有 COUNTRY_REGION 字典兼容迁移；完成业务切换前保留旧字典。",
            extra_data={"legacy_dictionary_item_id": str(item.id)},
        )
        ReferenceDictionary.objects.filter(pk=item.pk).update(english_name=english_name)

    for code, chinese_name, english_name, group_code, value_type, default_value, rules, sort_order in SYSTEM_PARAMETERS:
        definition = SystemParameterDefinition.objects.create(
            id=uuid.uuid5(MASTER_DATA_NAMESPACE, f"PARAM:{code}"),
            code=code,
            chinese_name=chinese_name,
            english_name=english_name,
            group_code=group_code,
            value_type=value_type,
            default_value=default_value,
            validation_rules=rules,
            status="ACTIVE",
            sort_order=sort_order,
        )
        SystemParameterValue.objects.create(definition=definition, draft_value=default_value)

    dictionary_options = {}
    for item in ReferenceDictionary.objects.filter(status="ACTIVE", archived_at__isnull=True).order_by(
        "category_code", "sort_order", "item_code"
    ):
        dictionary_options.setdefault(item.category_code, []).append(
            {
                "id": str(item.id),
                "code": item.item_code,
                "label": item.display_name,
                "english_label": item.english_name,
                "status": item.status,
                "sort_order": item.sort_order,
                "color": item.color,
                "extra": {**item.extra_data, "description": item.description},
            }
        )
    parameter_values = {
        code: default_value
        for code, _chinese, _english, _group, _type, default_value, _rules, _sort in SYSTEM_PARAMETERS
    }
    ConfigRelease.objects.create(
        version=1,
        status="PUBLISHED",
        notes="现有 11 类、67 项字典的兼容初始发布版本。",
        snapshot={"dictionary_options": dictionary_options, "system_parameters": parameter_values},
        published_at=timezone.now(),
    )


def clear_dictionary_type_links(apps, schema_editor):
    ReferenceDictionary = apps.get_model("reference_data", "ReferenceDictionary")
    ReferenceDictionary.objects.update(dictionary_type_id=None)


